const items = $input.all();
const returnItems = [];

// Verificar si hay items
if (!items || items.length === 0) {
  return [];
}

for (const item of items) {
  // Verificar que el item tenga la estructura correcta
  if (!item || !item.json || !item.json.start || !item.json.start.dateTime) {
    continue; // Saltar este item si no tiene la estructura correcta
  }

  let data = item.json;

  const dia = data.start.dateTime.split('T')[0];
  const inicio = data.start.dateTime.split('T')[1].substring(0, 5);
  const final = data.end.dateTime.split('T')[1].substring(0, 5);

  returnItems.push({
    json: {
      dia: dia,
      inicio: inicio, 
      final: final
    }
  });
}

return returnItems;

function calcularTurnosDisponibles() {
  const tiempoData = $('When Executed by Another Workflow').first().json;
  const feriadosData = $('feriados').first().json.feriadosEncontrados || [];
  const turnosOcupadosRaw = $('Code').all();

  // =====================================================
  // ⏱️ TIEMPO FIJO DE TURNO (2 HORAS)
  // =====================================================
  const tiempoTotal = 120; // minutos

  // =====================================================
  // 🕘 CONFIGURACIÓN HORARIA DEL TALLER
  // =====================================================
  const APERTURA = "08:00";
  const CIERRE = "18:00";

  const INICIO_ALMUERZO = "12:00";
  const FIN_ALMUERZO = "13:00";

  const INICIO_DESAYUNO = "09:30";
  const FIN_DESAYUNO = "09:45";

  const ID_CALENDARIO = 1; // si lo necesitás

  // =====================================================
  // 🔹 Helpers de tiempo
  // =====================================================
  function timeToMinutes(t) {
    const [h, m] = t.split(':').map(Number);
    return h * 60 + m;
  }

  function minutesToTime(min) {
    const h = Math.floor(min / 60);
    const m = min % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  }

  // =====================================================
  // 🔹 Helper formato fecha → "Jueves 04/12/2025"
  // =====================================================
  function formatoFecha(fechaStr) {
    const dias = ["Domingo","Lunes","Martes","Miércoles","Jueves","Viernes","Sábado"];
    const fecha = new Date(fechaStr);
    const diaSemana = dias[fecha.getDay()];
    const dd = fecha.getDate().toString().padStart(2, '0');
    const mm = (fecha.getMonth() + 1).toString().padStart(2, '0');
    const yyyy = fecha.getFullYear();
    return `${diaSemana} ${dd}/${mm}/${yyyy}`;
  }

  // =====================================================
  // 🔹 Turnos ocupados
  // =====================================================
  const turnosOcupados = [];

  turnosOcupadosRaw.forEach(item => {
    if (item.json && Array.isArray(item.json)) {
      turnosOcupados.push(...item.json);
    } else if (item.json && item.json.dia) {
      turnosOcupados.push(item.json);
    }
  });

  const fechasOcupadas = new Set();

  turnosOcupados.forEach(t => {
    if (t.dia && t.inicio && t.final) {
      const ini = timeToMinutes(t.inicio);
      const fin = timeToMinutes(t.final);
      for (let m = ini; m < fin; m += 15) {
        fechasOcupadas.add(`${t.dia}_${minutesToTime(m)}`);
      }
    }
  });

  // =====================================================
  // 🔹 Rango horario
  // =====================================================
  const apertura = timeToMinutes(APERTURA);
  const cierre = timeToMinutes(CIERRE);

  const iniAlm = timeToMinutes(INICIO_ALMUERZO);
  const finAlm = timeToMinutes(FIN_ALMUERZO);

  const iniDes = timeToMinutes(INICIO_DESAYUNO);
  const finDes = timeToMinutes(FIN_DESAYUNO);

  const feriados = new Set(feriadosData);
  const turnosDisponibles = [];

  const hoy = new Date();
  let fecha = new Date(hoy);
  fecha.setDate(fecha.getDate() + 2); // arranca en +2 días

  // =====================================================
  // 🔹 Buscar hasta 6 turnos
  // =====================================================
  while (turnosDisponibles.length < 6) {
    const fechaStr = fecha.toISOString().split('T')[0];
    const diaSemana = fecha.getDay();

    if (diaSemana >= 1 && diaSemana <= 5 && !feriados.has(fechaStr)) {
      const turnosDia = [];

      const estaDisponible = (inicio, duracion) => {
        const fin = inicio + duracion;

        // Almuerzo
        if (inicio < finAlm && fin > iniAlm) return false;

        // Desayuno
        if (inicio < finDes && fin > iniDes) return false;

        // Turnos ocupados
        for (let m = inicio; m < fin; m += 15) {
          if (fechasOcupadas.has(`${fechaStr}_${minutesToTime(m)}`)) return false;
        }

        return true;
      };

      for (let m = apertura; m + tiempoTotal <= cierre; m += 15) {
        if (estaDisponible(m, tiempoTotal)) {
          turnosDia.push({
            dia: fechaStr,
            inicio: minutesToTime(m),
            final: minutesToTime(m + tiempoTotal),
            Id_Calendario: ID_CALENDARIO,
            fechaFormato: formatoFecha(fechaStr)
          });
        }
      }

      turnosDisponibles.push(...turnosDia.slice(0, 2));
    }

    fecha.setDate(fecha.getDate() + 1);
  }

  // =====================================================
  // 🔹 Ordenar y devolver
  // =====================================================
  turnosDisponibles.sort((a, b) =>
    a.dia === b.dia
      ? a.inicio.localeCompare(b.inicio)
      : new Date(a.dia) - new Date(b.dia)
  );

  return {
    turnosDisponibles: turnosDisponibles.slice(0, 6),
    tiempoTotalCalculado: tiempoTotal
  };
}

// =====================================================
// ▶️ OUTPUT
// =====================================================
const resultado = calcularTurnosDisponibles();

return [{
  json: {
    turnosDisponibles: resultado.turnosDisponibles,
    tiempoTotalCalculado: resultado.tiempoTotalCalculado,
    cantidadTurnos: resultado.turnosDisponibles.length
  }
}];

function obtenerFeriados() {
  // Obtener los feriados del nodo anterior
  const feriadosData = $input.all(); // Obtiene todos los items del nodo anterior
  const feriados = [];

  // Extraer las fechas de los feriados del formato que recibes
  feriadosData.forEach(item => {
    if (item.json && item.json.start && item.json.start.date) {
      feriados.push(item.json.start.date);
    }
    // Si el feriado dura más de un día, también agregar las fechas intermedias
    if (item.json && item.json.end && item.json.end.date && item.json.start.date !== item.json.end.date) {
      const fechaInicio = new Date(item.json.start.date);
      const fechaFin = new Date(item.json.end.date);

      // Agregar todas las fechas entre inicio y fin
      const fechaActual = new Date(fechaInicio);
      while (fechaActual < fechaFin) {
        feriados.push(fechaActual.toISOString().split('T')[0]);
        fechaActual.setDate(fechaActual.getDate() + 1);
      }
    }
  });

  // Eliminar duplicados de la lista de feriados
  const feriadosUnicos = [...new Set(feriados)];

  return feriadosUnicos;
}

const feriadosEncontrados = obtenerFeriados();

return [{
  json: {
    feriadosEncontrados: feriadosEncontrados
  }
}];
